<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowDown, ArrowUp, Check, Copy, GripVertical, Plus, Trash2 } from 'lucide-vue-next'
import AppShell from '../components/AppShell.vue'
import { createTaskWithOutline, fetchLayouts, fetchMe } from '../api'
import type { AtomicLayout, AuthUser, SlideOutline } from '../types'

const router=useRouter();const user=ref<AuthUser>();const title=ref('');const slides=ref<SlideOutline[]>([{title:'封面',content_type:'title_slide'},{title:'核心观点',content_type:'content_slide'},{title:'结束页',content_type:'closing_slide'}]);const layouts=ref<AtomicLayout[]>([]);const selected=ref(0);const busy=ref(false);const error=ref('');const current=computed(()=>slides.value[selected.value]);
function label(type:string){return layouts.value.find(layout=>layout.name===type)?.display_name||type.replace(/_/g,' ')}
function add(){slides.value.push({title:'新页面',content_type:layouts.value[0]?.name||'content_slide'});selected.value=slides.value.length-1}
function duplicate(){if(!current.value)return;slides.value.splice(selected.value+1,0,structuredClone(current.value));selected.value++}
function remove(){if(slides.value.length<=1)return;slides.value.splice(selected.value,1);selected.value=Math.max(0,selected.value-1)}
function move(dir:number){const destination=selected.value+dir;if(destination<0||destination>=slides.value.length)return;[slides.value[selected.value],slides.value[destination]]=[slides.value[destination],slides.value[selected.value]];selected.value=destination}
async function generate(){error.value='';if(!title.value.trim()){error.value='请先写下演示标题';return}busy.value=true;try{const task=await createTaskWithOutline(title.value,{title:title.value,content_mode:'user_outline',slides:slides.value});router.push(`/dashboard?task=${task.id}`)}catch(e){error.value=e instanceof Error?e.message:'无法创建任务'}finally{busy.value=false}}
onMounted(async()=>{try{[user.value,layouts.value]=await Promise.all([fetchMe(),fetchLayouts()]);if(layouts.value.length)slides.value=slides.value.map(slide=>layouts.value.some(layout=>layout.name===slide.content_type)?slide:{...slide,content_type:layouts.value[0].name})}catch(e){error.value=e instanceof Error?e.message:'无法加载编排器'}})
</script>
<template><AppShell title="页面编排" subtitle="先定义叙事，再把每一页交给生成器" :email="user?.email" :guest="user?.is_guest" @new="router.push('/dashboard')"><div class="compose"><aside class="slide-list"><div class="compose-title"><span>演示标题</span><input v-model="title" placeholder="例如：储能解决方案提案" /></div><div class="list-top"><span>页面 {{ slides.length }}</span><button @click="add"><Plus :size="15" />添加页面</button></div><button v-for="(slide,index) in slides" :key="`${index}-${slide.title}`" class="slide-row" :class="{selected:index===selected}" @click="selected=index"><GripVertical :size="15" /><b>{{ String(index+1).padStart(2,'0') }}</b><span><strong>{{ slide.title || '未命名页面' }}</strong><small>{{ label(slide.content_type) }}</small></span></button></aside><section class="editor" v-if="current"><header><div><p>第 {{ String(selected+1).padStart(2,'0') }} 页</p><h2>安排这页要说什么</h2></div><div class="edit-actions"><button @click="move(-1)" :disabled="selected===0"><ArrowUp :size="16" /></button><button @click="move(1)" :disabled="selected===slides.length-1"><ArrowDown :size="16" /></button><button @click="duplicate"><Copy :size="16" /></button><button class="danger" @click="remove" :disabled="slides.length===1"><Trash2 :size="16" /></button></div></header><div class="page-paper"><label>页面标题<input v-model="current.title" placeholder="这页的核心结论" /></label><label>页面布局<select v-model="current.content_type"><option v-for="layout in layouts" :key="layout.name" :value="layout.name">{{ layout.display_name }}</option></select></label><div class="layout-note" v-if="layouts.find(l=>l.name===current.content_type)"><b>{{ layouts.find(l=>l.name===current.content_type)?.description }}</b><span v-if="layouts.find(l=>l.name===current.content_type)?.contract?.best_for?.length">适用于：{{ layouts.find(l=>l.name===current.content_type)?.contract?.best_for?.join('、') }}</span></div><label>内容指引<textarea class="resize-none" :value="String(current.content_plan?.summary || '')" rows="7" placeholder="写下事实、资料来源、希望强调的观点或图片意图。生成器会根据布局容量组织它们。" @input="current.content_plan = { ...(current.content_plan || {}), summary: ($event.target as HTMLTextAreaElement).value }" /></label></div></section><aside class="delivery"><p>交付前检查</p><div><Check :size="16" /><span><b>{{ slides.length }} 页叙事</b><small>可随时调整结构</small></span></div><div><Check :size="16" /><span><b>布局已选择</b><small>根据内容控制密度</small></span></div><button class="generate" :disabled="busy" @click="generate">{{ busy?'正在创建…':'开始生成' }}</button><p v-if="error" class="error">{{ error }}</p></aside></div></AppShell></template>
<style scoped>
.compose{height:calc(100vh - 78px);display:grid;grid-template-columns:270px minmax(0,1fr) 230px;background:#0b1c29}.slide-list{overflow:auto;padding:20px 13px;border-right:1px solid rgba(213,235,245,.1)}.compose-title span,.list-top span,.delivery>p{display:block;color:#7f9aa7;font:10px 'DM Mono',monospace;letter-spacing:.08em}.compose-title input{width:100%;margin-top:8px;padding:8px 2px;border:0;border-bottom:1px solid #41606a;outline:0;color:#e3f0ee;background:transparent;font:600 15px 'Noto Serif SC',serif}.list-top{display:flex;align-items:center;justify-content:space-between;margin:27px 4px 11px}.list-top button{display:flex;align-items:center;gap:3px;border:0;color:#85dfcf;background:transparent;font-size:11px}.slide-row{width:100%;display:flex;gap:8px;align-items:start;padding:12px 6px;border:0;border-radius:5px;color:#93abb5;background:transparent;text-align:left}.slide-row.selected{color:#eff8f5;background:#173743}.slide-row b{padding-top:1px;color:#5e7885;font:10px 'DM Mono',monospace}.slide-row span{min-width:0}.slide-row strong,.slide-row small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.slide-row strong{font-size:13px}.slide-row small{margin-top:3px;color:#73909a;font-size:11px}.editor{overflow:auto;padding:31px clamp(25px,6vw,90px)}.editor header{display:flex;justify-content:space-between;align-items:center;margin-bottom:27px}.editor header p{margin:0;color:#78cabb;font:10px 'DM Mono',monospace}.editor h2{margin:6px 0 0;font:700 27px 'Noto Serif SC',serif;letter-spacing:-.055em}.edit-actions{display:flex;gap:5px}.edit-actions button{width:32px;height:32px;display:grid;place-items:center;border:1px solid #3d5b66;border-radius:5px;color:#a5c0c6;background:transparent}.edit-actions .danger{color:#efaaa2}.edit-actions button:disabled{opacity:.35}.page-paper{max-width:720px;padding:clamp(24px,5vw,56px);color:#18303a;background:#f1f2e9;box-shadow:16px 20px 0 #163541}.page-paper label{display:block;margin-bottom:25px;color:#577077;font-size:12px;font-weight:700}.page-paper input,.page-paper select,.page-paper textarea{display:block;width:100%;margin-top:7px;padding:10px 2px;border:0;border-bottom:1px solid #b6c5bf;outline:0;color:#183441;background:transparent;font:600 18px 'Noto Serif SC',serif}.page-paper select{font:500 14px 'Noto Sans SC',sans-serif}.page-paper textarea{resize: none;font:400 14px/1.75 'Noto Sans SC',sans-serif}.layout-note{margin:-7px 0 25px;padding:11px 12px;color:#4e6b70;background:#dce9e2;border-left:2px solid #3e9f94;font-size:12px;line-height:1.6}.layout-note b,.layout-note span{display:block}.layout-note span{color:#628082}.delivery{padding:27px 17px;border-left:1px solid rgba(213,235,245,.1)}.delivery>div{display:flex;gap:8px;margin-top:17px;color:#79d9c8}.delivery b,.delivery small{display:block}.delivery b{color:#c3d7d9;font-size:12px}.delivery small{margin-top:2px;color:#728c97;font-size:11px}.generate{width:100%;margin-top:30px;padding:12px;border:0;border-radius:5px;color:#082d35;background:#76e0c9;font-weight:700}.error{color:#eea19b;font-size:12px;line-height:1.6}@media(max-width:950px){.compose{grid-template-columns:210px 1fr}.delivery{display:none}}@media(max-width:650px){.compose{grid-template-columns:1fr}.slide-list{display:none}.editor{padding:23px 18px}.page-paper{padding:24px}.editor h2{font-size:23px}}
</style>
